def format_bytes(n):
    """Return a human-readable size string for the given number of bytes."""
    KB = 1024
    if n < KB:
        return f"{n} B"
    if n < KB * KB:
        return f"{n / KB:.2f} KB"
    if n < KB * KB * KB:
        return f"{n / (KB ** 2):.2f} MB"
    return f"{n / (KB ** 3):.2f} GB"
